import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"Rust UI 框架","description":"","frontmatter":{"title":"Rust UI 框架","order":50},"headers":[],"relativePath":"client/rust/framework/index.md","filePath":"client/rust/framework/index.md"}`),a={name:`client/rust/framework/index.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="rust-ui-框架" tabindex="-1">Rust UI 框架 <a class="header-anchor" href="#rust-ui-框架" aria-label="Permalink to “Rust UI 框架”">​</a></h1><p>Rust 的 UI 生态在过去三年里从&quot;几乎不可用&quot;发展到&quot;多个框架各有擅长领域&quot;。与 JavaScript/TypeScript 在 Web 端的统治地位不同，Rust UI 框架的核心竞争维度是<strong>渲染方式</strong>和<strong>目标平台</strong>——不同选择决定了应用的性能、体积、开发体验和平台覆盖。</p><h2 id="核心分类" tabindex="-1">核心分类 <a class="header-anchor" href="#核心分类" aria-label="Permalink to “核心分类”">​</a></h2><p>Rust UI 框架按渲染架构分为三大流派。</p><p><strong>原生渲染（Native）</strong>：直接调用操作系统的图形 API 进行绘制，不依赖 Web 引擎。典型代表 iced、Slint。优势是极小的二进制体积（几 MB）、极低的资源占用、原生外观和手感。劣势是组件库不如 Web 生态丰富，自定义 UI 需要手动绘制。</p><p><strong>Web 渲染（WebView）</strong>：将 HTML/CSS/JS 嵌入 Rust 编译的原生壳中。典型代表 Tauri、Dioxus（桌面端使用 WebView）。优势是复用整个 Web 生态——任何 CSS 框架（Tailwind、Ant Design）、任何 JS 图表库、任何动画能力直接可用。劣势是二进制体积大（几十 MB）、内存占用高（内嵌完整浏览器引擎）、启动速度慢于原生。</p><p><strong>即时模式（Immediate Mode）</strong>：每一帧重新绘制整个 UI，不维护 UI 状态树。典型代表 egui。优势是无生命周期管理、无 borrow checker 与 UI 状态的复杂交互、代码极其简洁。劣势是性能不如保留模式（Retained Mode）在极复杂场景下的增量更新，且默认外观偏向&quot;工具/调试面板&quot;风格而非精致的桌面应用。</p><h2 id="框架总览" tabindex="-1">框架总览 <a class="header-anchor" href="#框架总览" aria-label="Permalink to “框架总览”">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>渲染方式</th><th>平台</th><th>语言</th><th>适合场景</th></tr></thead><tbody><tr><td><strong>Tauri</strong></td><td>WebView</td><td>桌面/Mobile</td><td>Rust 后端 + Web 前端</td><td>跨平台桌面应用、想复用 Web 能力的团队</td></tr><tr><td><strong>iced</strong></td><td>原生（wgpu/glow）</td><td>桌面/Web/Mobile</td><td>纯 Rust</td><td>桌面应用、需要原生控件的工具软件</td></tr><tr><td><strong>Slint</strong></td><td>原生（自研渲染）</td><td>桌面/嵌入式/MCU</td><td>Rust/C++/JS</td><td>嵌入式设备 UI、资源极度受限的环境</td></tr><tr><td><strong>egui</strong></td><td>即时模式（wgpu/glow）</td><td>桌面/Web</td><td>纯 Rust</td><td>开发工具、调试面板、数据可视化面板</td></tr><tr><td><strong>Dioxus</strong></td><td>WebView / 原生实验</td><td>桌面/Web/Mobile</td><td>纯 Rust</td><td>类 React 开发体验、全栈 Rust</td></tr><tr><td><strong>Leptos</strong></td><td>WASM + DOM</td><td>Web</td><td>纯 Rust</td><td>Web 应用、类 SolidJS 的细粒度响应式</td></tr><tr><td><strong>Rust Web</strong> (Yew/Sycamore)</td><td>WASM + DOM</td><td>Web</td><td>纯 Rust</td><td>Web 应用，各有组件模型偏好</td></tr></tbody></table><h2 id="选型指南" tabindex="-1">选型指南 <a class="header-anchor" href="#选型指南" aria-label="Permalink to “选型指南”">​</a></h2><p>需要精致的桌面原生应用、不依赖 Web 生态 → <strong>iced</strong>。拥有前端团队、想快速复刻已有 Web 应用为桌面版 → <strong>Tauri</strong>。嵌入式 Linux 或 MCU 上的 GUI → <strong>Slint</strong>（这个场景外框架无法覆盖）。开发工具/面板类应用、追求最少代码量 → <strong>egui</strong>。类 React 的 Rust 全栈开发体验 → <strong>Dioxus</strong>。纯 Web 应用、Rust 替代 JS → <strong>Leptos</strong>（细粒度响应式）。</p><p>iced、Slint、Tauri 各有独立篇幅展开介绍。</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};